REVOKE INSERT,UPDATE,DELETE ON public.firm_members FROM authenticated,anon;
CREATE FUNCTION public.posted_lines_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Posted journal lines are immutable; void the entry instead'; END $$;
CREATE TRIGGER posted_lines_immutable BEFORE UPDATE OR DELETE ON public.journal_lines FOR EACH ROW EXECUTE FUNCTION public.posted_lines_immutable();
CREATE FUNCTION public.posted_entry_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Posted entries cannot be deleted'; END IF; IF (to_jsonb(NEW)-'voided') IS DISTINCT FROM (to_jsonb(OLD)-'voided') OR (OLD.voided AND NOT NEW.voided) THEN RAISE EXCEPTION 'Only voiding is allowed on posted entries'; END IF; RETURN NEW; END $$;
CREATE TRIGGER posted_entry_immutable BEFORE UPDATE OR DELETE ON public.journal_entries FOR EACH ROW EXECUTE FUNCTION public.posted_entry_immutable();
CREATE POLICY firm_tenant ON public.firm AS RESTRICTIVE FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.firm_members m WHERE m.firm_id=firm.id AND m.user_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.clients c WHERE c.firm_id=firm.id AND public.is_company_client(c.id)));
CREATE OR REPLACE FUNCTION public.client_txn_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.client_id<>OLD.client_id OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.source<>OLD.source) THEN RAISE EXCEPTION 'Transaction ownership cannot be changed'; END IF; IF auth.uid() IS NOT NULL AND NOT public.has_company_access(NEW.client_id) AND (NOT public.client_can_enter(NEW.client_id) OR NEW.status<>'draft' OR NEW.source<>'client' OR NEW.created_by<>auth.uid() OR NEW.entry_id IS NOT NULL OR NEW.category_account_id IS NOT NULL OR NEW.bank_account_id IS NOT NULL) THEN RAISE EXCEPTION 'Client entries must wait for staff review'; END IF; RETURN NEW; END $$;